// This file is automatically generated. Do not edit it directly.
// Server-side Supabase client with service role key - bypasses RLS.
// Use this for admin operations in server functions and server routes only.
// For user-authenticated queries (with RLS), use the auth middleware instead.
import { createClient } from '@supabase/supabase-js';
import { getRequest } from '@tanstack/react-start/server';
import { env as cloudflareEnv } from 'cloudflare:workers';
import type { Database } from './types';

function isNewSupabaseApiKey(value: string): boolean {
  return value.startsWith('sb_publishable_') || value.startsWith('sb_secret_');
}

function createSupabaseFetch(supabaseKey: string): typeof fetch {
  return async (input, init) => {
    const headers = new Headers(
      typeof Request !== 'undefined' && input instanceof Request ? input.headers : undefined,
    );

    if (init?.headers) {
      new Headers(init.headers).forEach((value, key) => headers.set(key, value));
    }

    // New Supabase API keys are opaque strings, not bearer JWTs.
    if (isNewSupabaseApiKey(supabaseKey) && headers.get('Authorization') === `Bearer ${supabaseKey}`) {
      headers.delete('Authorization');
    }

    headers.set('apikey', supabaseKey);

    const url = input instanceof Request ? input.url : String(input);
    const method = init?.method ?? (input instanceof Request ? input.method : 'GET');
    let path = 'unknown';
    try {
      path = new URL(url).pathname;
    } catch {
      // Never log query strings, headers, or request bodies.
    }

    try {
      const response = await fetch(input, { ...init, headers });
      if (!response.ok) {
        let diagnostic: unknown = undefined;
        try {
          const body = await response.clone().json() as Record<string, unknown>;
          diagnostic = Object.fromEntries(
            ['code', 'message', 'details', 'hint'].filter((key) => {
              const value = body[key];
              return typeof value === 'string' || typeof value === 'number';
            }).map((key) => [key, body[key]]),
          );
        } catch {
          diagnostic = 'non-json error response';
        }
        const responseHeaders = Object.fromEntries(
          ['content-type', 'content-length', 'server', 'cf-ray', 'cf-cache-status', 'via',
            'x-supabase-api-version', 'sb-gateway-version', 'x-kong-proxy-latency',
            'x-kong-upstream-latency'].flatMap((name) => {
              const value = response.headers.get(name);
              return value ? [[name, value]] : [];
            }),
        );
        const authHeader = headers.get('Authorization');
        console.error('[Supabase admin fetch] HTTP response', JSON.stringify({
          method, path, status: response.status, statusText: response.statusText, diagnostic,
          responseHeaders,
          requestAuth: !authHeader ? 'absent' : authHeader.startsWith('Bearer ') ? 'bearer' : 'other',
          apiKeyType: supabaseKey.startsWith('sb_secret_') ? 'sb_secret' :
            supabaseKey.startsWith('sb_publishable_') ? 'sb_publishable' : 'legacy',
        }));
      }
      return response;
    } catch (error) {
      const e = error && typeof error === 'object' ? error as Record<string, unknown> : {};
      const cause = e.cause && typeof e.cause === 'object' ? e.cause as Record<string, unknown> : {};
      console.error('[Supabase admin fetch] network failure', JSON.stringify({
        method, path,
        name: typeof e.name === 'string' ? e.name : typeof (error as Error)?.constructor?.name === 'string' ? (error as Error).constructor.name : 'unknown',
        message: typeof e.message === 'string' ? e.message : String(error),
        causeName: typeof cause.name === 'string' ? cause.name : undefined,
        causeMessage: typeof cause.message === 'string' ? cause.message : undefined,
      }));
      throw error;
    }
  };
}

function createSupabaseAdminClient() {
  // Read the active Worker Preview bindings directly. process.env remains a fallback
  // for local Node-based tests, but must not override the Preview's isolated secrets.
  const runtimeEnv = cloudflareEnv as unknown as Record<string, string | undefined>;
  const SUPABASE_URL = runtimeEnv['SUPABASE_URL'] ?? process.env['SUPABASE_URL'];
  const SUPABASE_SERVICE_ROLE_KEY = runtimeEnv['SUPABASE_SERVICE_ROLE_KEY'] ?? process.env['SUPABASE_SERVICE_ROLE_KEY'];

  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
    const missing = [
      ...(!SUPABASE_URL ? ['SUPABASE_URL'] : []),
      ...(!SUPABASE_SERVICE_ROLE_KEY ? ['SUPABASE_SERVICE_ROLE_KEY'] : []),
    ];
    const message = `Missing Supabase environment variable(s): ${missing.join(', ')}. Connect Supabase in Lovable Cloud.`;
    console.error(`[Supabase] ${message}`);
    throw new Error(message);
  }

  return createClient<Database>(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, {
    global: {
      fetch: createSupabaseFetch(SUPABASE_SERVICE_ROLE_KEY),
    },
    auth: {
      storage: undefined,
      persistSession: false,
      autoRefreshToken: false,
    }
  });
}

type SupabaseClientInstance = ReturnType<typeof createSupabaseAdminClient>;
let _supabaseAdmin: SupabaseClientInstance | undefined;
const _requestClients = new WeakMap<Request, SupabaseClientInstance>();

function createSupabaseUserClient(token: string): SupabaseClientInstance {
  const runtimeEnv = cloudflareEnv as unknown as Record<string, string | undefined>;
  const url = runtimeEnv['SUPABASE_URL'] ?? process.env['SUPABASE_URL'];
  const publishableKey = runtimeEnv['SUPABASE_PUBLISHABLE_KEY'] ?? process.env['SUPABASE_PUBLISHABLE_KEY'];
  if (!url || !publishableKey) {
    throw new Error('Missing Supabase user client configuration.');
  }
  return createClient<Database>(url, publishableKey, {
    global: {
      fetch: createSupabaseFetch(publishableKey),
      headers: { Authorization: `Bearer ${token}` },
    },
    auth: { storage: undefined, persistSession: false, autoRefreshToken: false },
  });
}

function clientForCurrentRequest(): SupabaseClientInstance {
  let request: Request | undefined;
  try { request = getRequest(); } catch { request = undefined; }
  const authorization = request?.headers.get('authorization') ?? '';
  const match = /^Bearer ([^.\s]+\.[^.\s]+\.[^.\s]+)$/.exec(authorization);
  if (request && match) {
    const cached = _requestClients.get(request);
    if (cached) return cached;
    const client = createSupabaseUserClient(match[1]);
    _requestClients.set(request, client);
    return client;
  }
  if (!_supabaseAdmin) _supabaseAdmin = createSupabaseAdminClient();
  return _supabaseAdmin;
}

// In authenticated requests, preserve the caller's JWT so Supabase RLS applies.
// Only trusted non-user routes (the verified scheduler and public share resolver)
// fall back to the service-role client. Never cache a user client across requests.
export const supabaseAdmin = new Proxy({} as SupabaseClientInstance, {
  get(_, prop) {
    const client = clientForCurrentRequest();
    const value = Reflect.get(client, prop, client);
    return typeof value === 'function' ? value.bind(client) : value;
  },
});
